#!/bin/sh
# Code generated by our bespoke codegen `go-sdk-generator` (0.53.6).
# Run from the repository root; Qlty supplies the lockfile as the first argument.
set -eu

dockerfile="Dockerfile.generator"
go_version=$(awk '
  toupper($1) == "FROM" &&
  $2 ~ /^golang:/ &&
  toupper($3) == "AS" &&
  $4 == "build" {
    count++
    sub(/^golang:/, "", $2)
    version = $2
  }
  END {
    if (count != 1) exit 2
    print version
  }
' "$dockerfile") || {
	echo "Expected exactly one golang build stage in $dockerfile" >&2
	exit 2
}

if ! printf '%s\n' "$go_version" |
	grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+$'; then
	echo "Expected a pinned golang:X.Y.Z build stage" >&2
	exit 2
fi

scan_config=$(mktemp)
trap 'rm -f "$scan_config"' EXIT

printf 'ScanGoModVersion = true\nGoVersionOverride = "%s"\n' \
	"$go_version" >"$scan_config"

osv-scanner --config="$scan_config" \
	--lockfile="$1" --format sarif
